    assert (GSB0 : al_gsb AL = 0x1099f8) by (destruct IMG' as (_ & _ & _ & G); exact G). clear GSB.
    pose proof (munch_refl [(SHLO, SHHI); (0x63c080, 0x63c084); (0x106340, 0x106348); (0x1072b0, 0x1072b8); (0x106390, 0x106391);
                (0x65cd00, 0x65cd04); (0x65cae0, 0x65caf8); (bv_unsigned sp - 320, bv_unsigned sp)] m) as MUB.
    change (lx_hidden (munch [(SHLO, SHHI); (0x63c080, 0x63c084); (0x106340, 0x106348); (0x1072b0, 0x1072b8); (0x106390, 0x106391);
                (0x65cd00, 0x65cd04); (0x65cae0, 0x65caf8); (bv_unsigned sp - 320, bv_unsigned sp)] m m)) in MUB.
    pose proof (munch_refl [(0x65cd00, 0x65cd04); (0x65cae0, 0x65caf8); (bv_unsigned sp - 320, bv_unsigned sp)] m) as MU.
    pose proof (wmono_refl asegs m) as WM.
    destruct UG as [UG1 UG2 UG3 UG4 UG5 UG6 UG7 UG8 UG9 UG10]. destruct UC as [UC1 UC2 UC3 UC4 UC5 UC6].
